/* Small shared pool of decorative effects; game simulation owns its own RAF. */
(()=>{
const reduced=()=>window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
const ambient=document.createElement('div');ambient.className='ambient-sparkles';ambient.setAttribute('aria-hidden','true');
for(let i=0;i<14;i++){const s=document.createElement('span');s.style.setProperty('--x',(7+i*17)%100+'%');s.style.setProperty('--y',(13+i*23)%90+'%');s.style.setProperty('--delay',-(i%7)+'s');s.style.setProperty('--duration',(6+i%4)+'s');ambient.appendChild(s)}document.body.appendChild(ambient);
const world=document.createElement('div');world.className='world-atmosphere';world.setAttribute('aria-hidden','true');world.innerHTML='<div class="world-depth"></div><div class="godrays"></div><div class="volumetric-fog fog-far"></div><div class="volumetric-fog"></div><div class="depth-particles"></div>';
const dust=world.querySelector('.depth-particles');for(let i=0;i<18;i++){const p=document.createElement('span');p.className='depth-particle';const depth=i%3;p.style.cssText=`--px:${(i*37+11)%100}%;--py:${(i*19+7)%94}%;--size:${3+depth*3}px;--blur:${depth*.6}px;--opacity:${.3+depth*.12};--duration:${12+i%7}s;--delay:${-(i%13)}s`;dust.appendChild(p)}document.body.prepend(world);
// Keep the painted stone platform directly under the stationary hero's boots.
let gardenFrame=0;const syncGarden=()=>{cancelAnimationFrame(gardenFrame);gardenFrame=requestAnimationFrame(()=>{gardenFrame=0;const introImage=document.querySelector('body[data-screen="intro"] .intro-art>img'),introStats=document.querySelector('body[data-screen="intro"] .intro-attributes');if(introImage&&introStats){const box=introImage.parentElement.getBoundingClientRect(),short=innerHeight<=750,renderHeight=short?Math.min(box.height,box.width*1.5):Math.max(box.height,box.width*1.5),platformBase=renderHeight*(875/1536),target=introStats.getBoundingClientRect().top-box.top-20,zoom=Math.max(1,Math.min(1.4,target/platformBase));document.documentElement.style.setProperty('--intro-scene-zoom',String(zoom))}const avatar=document.querySelector('body[data-screen="home"] .hero-visual>.avatar');if(!avatar)return;const feet=avatar.getBoundingClientRect().bottom,scale=Math.max(innerWidth/1672,innerHeight/941,feet/630,(innerHeight-feet+30)/311);document.documentElement.style.setProperty('--garden-height',941*scale+'px');document.documentElement.style.setProperty('--garden-top',feet-630*scale+'px')})};
const main=document.querySelector('main');new ResizeObserver(syncGarden).observe(main);new MutationObserver(syncGarden).observe(main,{childList:true});window.addEventListener('resize',syncGarden,{passive:true});syncGarden();
let parallaxFrame=0,lastX=0,lastY=0;const resetDepth=()=>{cancelAnimationFrame(parallaxFrame);parallaxFrame=0;document.documentElement.style.setProperty('--parallax-x','0px');document.documentElement.style.setProperty('--parallax-y','0px')};
document.addEventListener('pointermove',e=>{if(reduced()||document.hidden)return;lastX=(e.clientX/innerWidth-.5)*24;lastY=(e.clientY/innerHeight-.5)*18;if(parallaxFrame)return;parallaxFrame=requestAnimationFrame(()=>{parallaxFrame=0;document.documentElement.style.setProperty('--parallax-x',lastX+'px');document.documentElement.style.setProperty('--parallax-y',lastY+'px')})},{passive:true});document.documentElement.addEventListener('pointerleave',resetDepth,{passive:true});window.matchMedia?.('(prefers-reduced-motion: reduce)').addEventListener?.('change',resetDepth);document.addEventListener('visibilitychange',()=>{if(document.hidden)resetDepth()});
const pool=new Set();window.WonderEffects={clear(){for(const p of pool)p.remove();pool.clear()}};document.addEventListener('pointerdown',event=>{if(document.hidden||reduced())return;const button=event.target.closest?.('button');if(!button||button.disabled)return;const palette=['#fff8be','#bef6df','#f8c7e2','#c3edff'];for(let i=0;i<7&&pool.size<42;i++){const p=document.createElement('span'),angle=i*Math.PI*2/7;p.className='tap-spark';p.setAttribute('aria-hidden','true');p.style.left=event.clientX+'px';p.style.top=event.clientY+'px';p.style.setProperty('--dx',Math.cos(angle)*(27+i%3*12)+'px');p.style.setProperty('--dy',Math.sin(angle)*(27+i%3*12)-12+'px');p.style.setProperty('--spark-color',palette[i%palette.length]);pool.add(p);document.body.appendChild(p);p.addEventListener('animationend',()=>{p.remove();pool.delete(p)},{once:true});setTimeout(()=>{p.remove();pool.delete(p)},850)}},{passive:true});
document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('app-hidden',document.hidden);if(document.hidden){for(const p of pool)p.remove();pool.clear()}});
})();
